import { add, divide } from "./math";

describe("add", () => {
  it("adds two positive integers", () => {
    expect(add(2, 3)).toBe(5);
    expect(add(10, 4)).toBe(14);
  });

  it("adds negative numbers and zero", () => {
    expect(add(-2, -3)).toBe(-5);
    expect(add(0, 7)).toBe(7);
  });

  it("handles mixed signs", () => {
    expect(add(-5, 12)).toBe(7);
    expect(add(5, -12)).toBe(-7);
  });

  it("preserves decimal addition result", () => {
    expect(add(0.1, 0.2)).toBeCloseTo(0.3, 10);
  });
});

describe("divide", () => {
  it("divides two positive numbers", () => {
    expect(divide(10, 2)).toBe(5);
    expect(divide(9, 3)).toBe(3);
  });

  it("returns a negative quotient for mixed signs", () => {
    expect(divide(-9, 3)).toBe(-3);
    expect(divide(9, -3)).toBe(-3);
  });

  it("handles zero numerator", () => {
    expect(divide(0, 5)).toBe(0);
  });

  it("throws when dividing by zero", () => {
    expect(() => divide(5, 0)).toThrow("Cannot divide by zero");
  });

  it("supports fractional results", () => {
    expect(divide(1, 2)).toBe(0.5);
    expect(divide(7, 2)).toBe(3.5);
  });
});
